package inventory

import (
	"bytes"
	"context"
	"fmt"
	"image"
	"image/color"
	"image/png"
)

// DemoManifest describes reproducible scenarios, not a parallel registry. IDs are
// generated by the real services once; reruns never replace existing objects.
type DemoManifest struct {
	Version                                                                      int        `json:"version"`
	Locations                                                                    []Location `json:"locations"`
	PhotoIDs                                                                     []string   `json:"photo_ids"`
	ActiveDormitories, ActiveRooms, ActivePlaces, Free, Maintenance, Unavailable int64
}
type DemoSeeder struct {
	inventory *Service
	photos    *PhotoService
}

func NewDemoSeeder(s *Service, p *PhotoService) *DemoSeeder {
	return &DemoSeeder{inventory: s, photos: p}
}
func (s *DemoSeeder) Seed(ctx context.Context, writer, commandant string) (DemoManifest, error) {
	result := DemoManifest{Version: 1, ActiveDormitories: 1, ActiveRooms: 2, ActivePlaces: 5, Free: 3, Maintenance: 1, Unavailable: 1}
	exists, err := s.inventory.repo.HasInventory(ctx)
	if err != nil {
		return result, err
	}
	if exists {
		return result, fmt.Errorf("demo requires an empty registry")
	}
	remember := func(p Location) { result.Locations = append(result.Locations, p) }
	save := func(p Location, kind Kind, draft Draft) (Node, error) {
		return s.inventory.Save(ctx, writer, p, kind, draft, true, 0)
	}
	p := Location{DormitoryID: "dev-dorm-1"}
	_, err = save(p, Dormitory, Draft{Name: "Демо: Алатау / Үлгі: Алатау", Address: "Демонстрационный кампус / Үлгі кампусы", Operator: "Демо-оператор", UseBasis: "DEMO — не реальные сведения", Contacts: "demo@example.invalid", Description: "Демонстрационный фонд. Үлгі деректері. Создан только явной командой.", Published: true})
	if err != nil {
		return result, err
	}
	remember(p)
	building, err := save(p, Building, Draft{Name: "Учебный корпус / Үлгі ғимарат"})
	if err != nil {
		return result, err
	}
	p.BuildingID = building.ID
	remember(p)
	floor1, err := save(p, Floor, Draft{Number: "1"})
	if err != nil {
		return result, err
	}
	p.FloorID = floor1.ID
	remember(p)
	floor2, err := save(Location{DormitoryID: p.DormitoryID, BuildingID: p.BuildingID}, Floor, Draft{Number: "2"})
	if err != nil {
		return result, err
	}
	otherFloor := Location{DormitoryID: p.DormitoryID, BuildingID: p.BuildingID, FloorID: floor2.ID}
	remember(otherFloor)
	var firstRoom, archivedRoom Location
	for _, spec := range []struct {
		number, capacity, price string
		parent                  Location
		accessible              bool
	}{{"101", "3", "1500000", p, true}, {"102", "2", "1200000", p, false}, {"201", "1", "1800000", otherFloor, true}} {
		node, err := save(spec.parent, Room, Draft{Number: spec.number, Capacity: spec.capacity, Area: "20.25", Equipment: "Кровать, стол, шкаф / Төсек, үстел, шкаф", Sanitary: "Душ и кухня на этаже / Қабаттағы душ пен асүй", Accessible: spec.accessible, AccessibilityNotes: "Демо: доступный вход / Үлгі: қолжетімді кіреберіс", PriceMinor: spec.price, Currency: "KZT", PricePeriod: "месяц"})
		if err != nil {
			return result, err
		}
		room := spec.parent
		room.RoomID = node.ID
		remember(room)
		count := 2
		if spec.number == "101" {
			count = 3
			firstRoom = room
		}
		if spec.number == "201" {
			count = 1
			archivedRoom = room
		}
		for i := 1; i <= count; i++ {
			bed, err := save(room, Bed, Draft{Number: fmt.Sprint(i), Basis: "DEMO: ввод места / Орынды енгізу"})
			if err != nil {
				return result, err
			}
			location := room
			location.BedID = bed.ID
			remember(location)
			if spec.number == "101" && i > 1 {
				target := BedMaintenance
				if i == 3 {
					target = BedUnavailable
				}
				if _, err = s.inventory.ChangeBedStatus(ctx, commandant, location, bed.Version, target, "DEMO: учебное изменение / Үлгі өзгерісі"); err != nil {
					return result, err
				}
			}
			if spec.number == "201" {
				if _, err = s.inventory.ArchiveWithBasis(ctx, writer, location, bed.Version, true, "DEMO: архив / Мұрағат"); err != nil {
					return result, err
				}
			}
		}
	}
	// Deterministic test pixels, explicitly labelled as demonstration images.
	// No external assets or real personal data are downloaded or inserted.
	for index, owner := range []Location{{DormitoryID: p.DormitoryID}, firstRoom, archivedRoom} {
		pixels := image.NewRGBA(image.Rect(0, 0, 640, 400))
		for y := 0; y < 400; y++ {
			for x := 0; x < 640; x++ {
				v := uint8(((x/40 + y/40 + index) % 2) * 45)
				pixels.SetRGBA(x, y, color.RGBA{R: 25 + v, G: 90 + v, B: 115 + v, A: 255})
			}
		}
		var buffer bytes.Buffer
		if err = png.Encode(&buffer, pixels); err != nil {
			return result, err
		}
		photo, err := s.photos.Upload(ctx, writer, owner, bytes.NewReader(buffer.Bytes()), PhotoDraft{Description: "Демонстрационное изображение / Үлгі кескіні", Position: 0, Primary: true})
		if err != nil {
			return result, err
		}
		result.PhotoIDs = append(result.PhotoIDs, photo.ID)
	}
	if _, err = s.inventory.Archive(ctx, writer, archivedRoom, 1, true); err != nil {
		return result, err
	}
	if _, err = s.inventory.Archive(ctx, writer, otherFloor, 1, true); err != nil {
		return result, err
	}
	return result, nil
}
